const items = $input.all();
const results = [];
for (const item of items) {
  const text = item.json.ParsedResults?.[0]?.ParsedText || '';
  const effectiveDate = (text.match(/(?:effective|start)\s*date\s*:?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i) || [])[1] || '';
  const expiryDate = (text.match(/(?:expiry|end|termination)\s*date\s*:?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})/i) || [])[1] || '';
  const parties = text.match(/(?:between|party\s*[ab12])\s*:?\s*([A-Z][A-Za-z\s&.,]+(?:Ltd|LLC|Inc|Corp|Co)?)/gi) || [];
  const amounts = text.match(/\$[\d,]+\.?\d*/g) || [];
  const terms = text.match(/(?:term|duration)\s*:?\s*(.+?)(?:\.|\n)/i) || [];
  results.push({
    json: {
      effectiveDate,
      expiryDate,
      parties: parties.map(p => p.trim()),
      totalAmounts: amounts,
      termDuration: (terms[1] || '').trim(),
      contractType: (text.match(/(?:agreement|contract)\s+(?:type|for)\s*:?\s*(.+?)(?:\.|\n)/i) || [])[1] || 'General',
      extractedSections: text.substring(0, 2000)
    }
  });
}
return results;

